    public func encode(to encoder: any Encoder) throws {
        switch self {
        case .stopped:
            var _container = encoder.singleValueContainer()
            try _container.encode("Stopped")
        case .prompt(let text, let steered):
            var _container = encoder.container(keyedBy: Tag.self)
            var _fields = _container.nestedContainer(keyedBy: PromptKeys.self, forKey: .prompt)
            try _fields.encode(text, forKey: .text)
            try _fields.encode(steered, forKey: .steered)
        case .prose(let text, let streaming, let workingNote):
            var _container = encoder.container(keyedBy: Tag.self)
            var _fields = _container.nestedContainer(keyedBy: ProseKeys.self, forKey: .prose)
            try _fields.encode(text, forKey: .text)
            try _fields.encode(streaming, forKey: .streaming)
            try _fields.encode(workingNote, forKey: .workingNote)
        case .thinking(let text, let open, let durationMs):
            var _container = encoder.container(keyedBy: Tag.self)
            var _fields = _container.nestedContainer(keyedBy: ThinkingKeys.self, forKey: .thinking)
            try _fields.encode(text, forKey: .text)
            try _fields.encode(open, forKey: .open)
            try _fields.encodeIfPresent(durationMs, forKey: .durationMs)
        case .toolCall(let server, let tool, let fact, let state, let result):
            var _container = encoder.container(keyedBy: Tag.self)
            var _fields = _container.nestedContainer(keyedBy: ToolCallKeys.self, forKey: .toolCall)
            try _fields.encode(server, forKey: .server)
            try _fields.encode(tool, forKey: .tool)
            try _fields.encode(fact, forKey: .fact)
            try _fields.encode(state, forKey: .state)
            try _fields.encode(result, forKey: .result)
        case .fileChange(let files, let state):
