        self.openBelow = openBelow
        self.unresolvedFailure = unresolvedFailure
        self.counts = counts
        self.recent = recent
    }

    private enum CodingKeys: String, CodingKey {
        case first
        case last
        case steps
        case live
        case openBelow = "open_below"
        case unresolvedFailure = "unresolved_failure"
        case counts
        case recent
    }
}

